CREATE COLUMN TABLE "TEST_AP"."ORCJ" ("Id" INTEGER CS_INT NOT NULL , "ResCode" NVARCHAR(50), "WhsCode" NVARCHAR(8), "CapDate" LONGDATE CS_LONGDATE, "CapType" NVARCHAR(1) DEFAULT 'I', "Capacity" DECIMAL(21,6) CS_FIXED, "SrcObjType" INTEGER CS_INT DEFAULT -1, "SrcAbsEnt" INTEGER CS_INT, "SrcLine" INTEGER CS_INT, "BaseObjTyp" INTEGER CS_INT DEFAULT -1, "BaseAbsEnt" INTEGER CS_INT, "BaseLine" INTEGER CS_INT, "ActionType" SMALLINT CS_INT DEFAULT -1, "OwnObjTyp" INTEGER CS_INT DEFAULT -1, "OwnAbsEnt" INTEGER CS_INT, "OwnLine" INTEGER CS_INT, "RevdObjTyp" INTEGER CS_INT DEFAULT -1, "RevdAbsEnt" INTEGER CS_INT, "RevdLine" INTEGER CS_INT, "MemoSrc" NVARCHAR(1) DEFAULT '-', "Memo" NCLOB MEMORY THRESHOLD 1000, "SngRunCap" DECIMAL(21,6) CS_FIXED, "MemoSrcSng" NVARCHAR(1) DEFAULT '-', "MemoSng" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("Id")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."ORCJ" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$ResCode$WhsCode$CapDate$CapType$','ResCode','WhsCode','CapDate','CapType'));
ALTER TABLE "TEST_AP"."ORCJ" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$BaseObjTyp$BaseAbsEnt$BaseLine$','BaseObjTyp','BaseAbsEnt','BaseLine'));
ALTER TABLE "TEST_AP"."ORCJ" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$OwnObjTyp$OwnAbsEnt$OwnLine$','OwnObjTyp','OwnAbsEnt','OwnLine'));
CREATE INDEX "ORCJ_RWDT" ON "TEST_AP"."ORCJ" ( "ResCode" ASC, "WhsCode" ASC, "CapDate" ASC, "CapType" ASC );
CREATE INDEX "ORCJ_BASE_DOC" ON "TEST_AP"."ORCJ" ( "BaseObjTyp" ASC, "BaseAbsEnt" ASC, "BaseLine" ASC );
CREATE INDEX "ORCJ_OWNING_DOC" ON "TEST_AP"."ORCJ" ( "OwnObjTyp" ASC, "OwnAbsEnt" ASC, "OwnLine" ASC )